const clock=new THREE.Clock();let worldTime=0;const tmp=new THREE.Vector3();
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);worldTime+=dt;if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)ui.toast.classList.remove('show')}
if(state.playing){state.elapsed+=dt;state.distance+=dt*(26+Math.min(state.elapsed*.22,10));const speed=25+Math.min(state.elapsed*.22,10);state.danger=Math.min(1,state.danger+dt*.0042);state.invuln=Math.max(0,state.invuln-dt);state.hitCooldown=Math.max(0,state.hitCooldown-dt);
state.lane+=(state.targetLane-state.lane)*Math.min(1,dt*11);player.position.x=laneX(state.lane);player.position.y+=state.jumpV*dt;state.jumpV-=19*dt;if(player.position.y<=0){player.position.y=0;state.jumpV=0;state.jumping=false}player.rotation.z=Math.sin(worldTime*13)*.035+(state.targetLane-state.lane)*.08;player.rotation.x=Math.sin(worldTime*15)*.055;player.scale.y=1+(state.jumping?.035:Math.sin(worldTime*18)*.035);arms.forEach((a,i)=>{a.rotation.x=Math.sin(worldTime*16+i*Math.PI)*.7;a.rotation.z=(i===0?-.6:.6)+Math.sin(worldTime*16+i*Math.PI)*.4});legs.forEach((l,i)=>{l.rotation.x=Math.sin(worldTime*16+i*Math.PI)*.65});
for(const m of markers){m.position.z+=speed*dt;if(m.position.z>8)m.position.z-=159.6}
for(const p of jungle){p.position.z+=speed*dt*.82;if(p.position.z>15)p.position.z-=167}
for(const p of props){if(!p.group.visible)continue;p.group.position.z+=speed*dt;if(p.type==='snack')p.group.rotation.y+=dt*1.6;if(p.group.position.z>2.2){if(p.type==='snack'&&!p.taken){p.taken=true;p.group.visible=false;continue}const hitLane=Math.abs(p.group.position.x-player.position.x)<1.12;const close=Math.abs(p.group.position.z-player.position.z)<1.05;const airborne=player.position.y>(p.type==='log'?.92:1.55);if(hitLane&&close&&!airborne&&state.invuln<=0&&state.hitCooldown<=0){state.hitCooldown=.9;state.invuln=.9;state.danger=Math.min(1,state.danger+.13);player.rotation.z=rand(-.55,.55);showToast(p.type==='bird'?'TOUCAN! 0 / YOU 1 (IT WAS A DRAW)':'BONK! The jungle says hello.');if(state.danger>=1)endGame()}if(p.group.position.z>4){p.group.position.z-=154;p.group.position.x=laneX(Math.floor(Math.random()*3)-1);if(p.type==='snack'){p.taken=false;p.group.visible=true}else if(Math.random()<.12){p.type='bird'}else p.type='log'}}}
// The anaconda bobs and sways as it gains on the explorer. Its whole body trails behind its huge head.
const chaseZ=7.8-state.danger*6.4;snakeHead.position.set(Math.sin(worldTime*2.6)*.35,1.35+Math.sin(worldTime*4)*.16,chaseZ);snakeHead.rotation.y=Math.PI+Math.sin(worldTime*2)*.13;snakeHead.rotation.z=Math.sin(worldTime*3)*.07;for(let i=0;i<segments.length;i++){const t=i/segments.length;const seg=segments[i];seg.position.set(Math.sin(worldTime*2.4-t*5)*(.35+t*.5),.75+Math.sin(worldTime*4-t*3)*.18,chaseZ+1.05+i*.48);const pulse=1+Math.sin(worldTime*5-i*.45)*.045;seg.scale.set(seg.scale.x*pulse,seg.scale.y*pulse,seg.scale.z*pulse)}
// Moment of peril: a fast lunge, a silly bonk, then the snake reluctantly winds back.
if(state.danger>.94&&state.playing&&state.invuln<=0&&Math.random()<dt*.75){state.danger=Math.min(1,state.danger+.025);snakeHead.position.z=player.position.z+1.1;if(state.danger>=1)endGame()}
const camTargetX=player.position.x*.3;camera.position.x+=(camTargetX-camera.position.x)*dt*2.3;camera.position.y=4.15+Math.sin(worldTime*14)*.045;camera.lookAt(player.position.x*.18,1.35,-4.5);ui.distance.textContent=String(Math.floor(state.distance)).padStart(3,'0');ui.snacks.textContent=String(state.snacks).padStart(2,'0');ui.danger.style.width=`${Math.round(state.danger*100)}%`;ui.dangerLabel.textContent=state.danger<.34?'CHILL':state.danger<.66?'SUSPICIOUS':state.danger<.9?'OH NO':'NOM NOM';ui.dangerLabel.style.color=state.danger>.72?'#ff785f':'#d7ff48';
}else{player.position.y=Math.sin(worldTime*2)*.025;player.rotation.y=Math.sin(worldTime*.7)*.07;snakeHead.position.set(Math.sin(worldTime*1.7)*.28,1.35+Math.sin(worldTime*3.4)*.15,8.5);snakeHead.rotation.y=Math.PI+Math.sin(worldTime*1.6)*.1;for(let i=0;i<segments.length;i++){const seg=segments[i];seg.position.set(Math.sin(worldTime*1.7-i*.22)*.35,.72+Math.sin(worldTime*2-i*.23)*.1,9.5+i*.48)}}
renderer.render(scene,camera)}animate();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
</script>
