// A tiny explorer with a huge hat and absolutely no survival instincts.
const player=new THREE.Group();scene.add(player);player.position.set(0,0,1);const body=new THREE.Mesh(new THREE.SphereGeometry(.48,16,12),mats.player);body.scale.set(.83,1.15,.68);body.position.y=1.08;body.castShadow=true;player.add(body);const belly=new THREE.Mesh(new THREE.SphereGeometry(.28,12,9),mat(0xffebad));belly.scale.set(1,.95,.25);belly.position.set(0,.98,.44);player.add(belly);const shorts=new THREE.Mesh(new THREE.CylinderGeometry(.34,.38,.4,10),mats.shorts);shorts.position.y=.64;shorts.castShadow=true;player.add(shorts);const head=new THREE.Mesh(new THREE.SphereGeometry(.48,16,12),mats.player);head.position.y=1.9;head.castShadow=true;player.add(head);const hat=new THREE.Mesh(new THREE.CylinderGeometry(.44,.48,.12,12),mat(0xf6f1dc));hat.position.y=2.28;player.add(hat);const crown=new THREE.Mesh(new THREE.CylinderGeometry(.28,.34,.32,10),mat(0xf6f1dc));crown.position.y=2.48;player.add(crown);
for(const x of [-.19,.19]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.09,10,8),mats.white);eye.position.set(x,1.98,.4);player.add(eye);const pupil=new THREE.Mesh(new THREE.SphereGeometry(.043,8,6),mats.black);pupil.position.set(x+.025,1.97,.48);player.add(pupil)}const mouth=new THREE.Mesh(new THREE.TorusGeometry(.09,.025,6,12,Math.PI),mats.black);mouth.position.set(0,1.78,.44);mouth.rotation.z=Math.PI;player.add(mouth);const arms=[],legs=[];for(const side of [-1,1]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.48,4,8),mats.player);arm.position.set(side*.48,1.2,0);arm.rotation.z=side*-.6;player.add(arm);arms.push(arm);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.14,.42,4,8),mats.shorts);leg.position.set(side*.2,.36,0);player.add(leg);legs.push(leg)}
const snake=new THREE.Group();scene.add(snake);const segments=[];for(let i=0;i<22;i++){const radius=.22+.2*Math.sin(i/21*Math.PI),s=new THREE.Mesh(new THREE.SphereGeometry(1,12,9),i%3===0?mats.snakeDark:mats.snake);s.scale.set(radius*1.35,radius,radius*1.15);s.userData.baseScale=s.scale.clone();s.castShadow=true;snake.add(s);segments.push(s)}const snakeHead=new THREE.Group();const headMesh=new THREE.Mesh(new THREE.SphereGeometry(.65,16,12),mats.snake);headMesh.scale.set(1.35,.78,1.35);headMesh.position.y=.1;snakeHead.add(headMesh);const snout=new THREE.Mesh(new THREE.SphereGeometry(.35,12,8),mats.snake);snout.scale.set(1.45,.65,1);snout.position.set(0,-.05,.62);snakeHead.add(snout);for(const x of [-.34,.34]){const ew=new THREE.Mesh(new THREE.SphereGeometry(.2,12,8),mats.white);ew.position.set(x,.43,.42);snakeHead.add(ew);const p=new THREE.Mesh(new THREE.SphereGeometry(.095,10,8),mats.black);p.position.set(x,.43,.58);snakeHead.add(p);const brow=new THREE.Mesh(new THREE.SphereGeometry(.22,8,6),mats.snakeDark);brow.scale.set(1,.3,.5);brow.position.set(x,.61,.35);snakeHead.add(brow)}const snakeMouth=new THREE.Mesh(new THREE.TorusGeometry(.3,.055,8,16,Math.PI),mat(0x752a39));snakeMouth.position.set(0,-.23,.57);snakeMouth.rotation.x=.1;snakeHead.add(snakeMouth);const tongue=new THREE.Mesh(new THREE.ConeGeometry(.075,.6,6),mats.pink);tongue.rotation.x=Math.PI/2;tongue.position.set(0,-.32,.93);snakeHead.add(tongue);snake.add(snakeHead);
const ui={overlay:document.querySelector('#overlay'),start:document.querySelector('#startButton'),subtitle:document.querySelector('#subtitle'),footnote:document.querySelector('#footnote'),funny:document.querySelector('#funnyNote'),danger:document.querySelector('#dangerMeter'),dangerLabel:document.querySelector('#dangerLabel'),snacks:document.querySelector('#snackCount'),distance:document.querySelector('#distance'),toast:document.querySelector('#toast')};const state={playing:false,over:false,lane:0,targetLane:0,jumpV:0,jumping:false,elapsed:0,distance:0,snacks:0,danger:0,toastTimer:0,invuln:0,hitCooldown:0};
function start(){state.playing=true;state.over=false;state.elapsed=0;state.distance=0;state.danger=.16;state.snacks=0;state.lane=0;state.targetLane=0;state.invuln=0;player.position.set(0,0,1);ui.overlay.classList.add('hidden');document.body.classList.add('playing');ui.distance.textContent='000';ui.snacks.textContent='00';ui.footnote.textContent='No map. No plan. One very big noodle.';ui.funny.textContent='Tip: the snake is faster when you look back. (Probably.)';for(let i=0;i<props.length;i++){const p=props[i];p.group.visible=true;if(p.type==='snack')p.taken=false;p.group.position.z=-18-Math.floor(i/2)*11-(i%2?5:0);p.group.position.x=laneX(Math.floor(Math.random()*3)-1)}for(const m of markers)m.position.z=-Math.random()*160}
